// Package rt is the runtime core that code generated by the Alder compiler
// imports: the containers behind Maybe, Result, Dict and Date, and the
// small helpers the emitter uses for operators and string interpolation.
package rt

import (
	"fmt"
	"net/url"
	"reflect"
	"slices"
	"strconv"
	"strings"
	"time"
)

// Maybe is Alder's `Maybe a`. The zero value is Nothing.
type Maybe[T any] struct {
	Ok  bool
	Val T
}

// Just wraps a value.
func Just[T any](v T) Maybe[T] { return Maybe[T]{Ok: true, Val: v} }

// Nothing is the empty Maybe.
func Nothing[T any]() Maybe[T] { return Maybe[T]{} }

// Result is Alder's `Result e a`.
type Result[E, T any] struct {
	IsOk bool
	Val  T
	Err  E
}

// Ok is a successful Result.
func Ok[E, T any](v T) Result[E, T] { return Result[E, T]{IsOk: true, Val: v} }

// Err is a failed Result.
func Err[E, T any](e E) Result[E, T] { return Result[E, T]{Err: e} }

// Dict is Alder's `Dict k v`: an immutable map that remembers the order in
// which keys were first inserted. The zero value is the empty Dict.
// Insert and Remove return a new Dict and never change the receiver.
//
// A key may be of any Alder type (a List, a record, a Time, …), so the map
// is keyed by the key's canonical encoding, Key(k): two keys are the same
// key exactly when their encodings are equal, which is when they are Eq.
type Dict[K, V any] struct {
	m    map[string]V
	keys []K
	encs []string // Key of each of keys
}

// Get looks a key up.
func (d Dict[K, V]) Get(k K) (V, bool) {
	v, ok := d.m[Key(k)]
	return v, ok
}

// Has reports whether the key is present.
func (d Dict[K, V]) Has(k K) bool {
	_, ok := d.m[Key(k)]
	return ok
}

// Len is the number of entries.
func (d Dict[K, V]) Len() int { return len(d.keys) }

// Keys returns the keys in insertion order, as a fresh slice.
func (d Dict[K, V]) Keys() []K { return append([]K{}, d.keys...) }

// Values returns the values in key insertion order.
func (d Dict[K, V]) Values() []V {
	vs := make([]V, len(d.keys))
	for i, e := range d.encs {
		vs[i] = d.m[e]
	}
	return vs
}

// Insert returns a Dict with k bound to v. A key already present keeps its
// position (and its first spelling, e.g. the first Time zone); a new key
// goes last.
func (d Dict[K, V]) Insert(k K, v V) Dict[K, V] {
	c := d.clone()
	c.Put(k, v)
	return c
}

// Remove returns a Dict without k.
func (d Dict[K, V]) Remove(k K) Dict[K, V] {
	enc := Key(k)
	if _, ok := d.m[enc]; !ok {
		return d
	}
	c := Dict[K, V]{m: make(map[string]V, len(d.m)), keys: make([]K, 0, len(d.keys)), encs: make([]string, 0, len(d.encs))}
	for i, e := range d.encs {
		if e != enc {
			c.keys = append(c.keys, d.keys[i])
			c.encs = append(c.encs, e)
			c.m[e] = d.m[e]
		}
	}
	return c
}

// Put binds k to v in place. It is for building a Dict that no Alder code
// has seen yet (e.g. inside a stdlib function); everything else uses Insert.
func (d *Dict[K, V]) Put(k K, v V) {
	if d.m == nil {
		d.m = map[string]V{}
	}
	enc := Key(k)
	if _, ok := d.m[enc]; !ok {
		d.keys = append(d.keys, k)
		d.encs = append(d.encs, enc)
	}
	d.m[enc] = v
}

// Equal reports whether both dicts hold the same keys with Eq values.
// Insertion order is ignored.
func (d Dict[K, V]) Equal(o Dict[K, V]) bool {
	if len(d.m) != len(o.m) {
		return false
	}
	for e, v := range d.m {
		ov, ok := o.m[e]
		if !ok || !Eq(v, ov) {
			return false
		}
	}
	return true
}

func (d Dict[K, V]) eqAny(o any) bool { return d.Equal(o.(Dict[K, V])) }

// keyAny is the Dict's own canonical encoding, for a Dict used inside a key:
// its entries sorted by key encoding, so that insertion order is ignored as
// Equal ignores it.
func (d Dict[K, V]) keyAny(b *strings.Builder) {
	encs := slices.Clone(d.encs)
	slices.Sort(encs)
	b.WriteString("d")
	for _, e := range encs {
		writeLen(b, e)
		keyValue(b, reflect.ValueOf(d.m[e]))
	}
	b.WriteString(")")
}

func (d Dict[K, V]) clone() Dict[K, V] {
	c := Dict[K, V]{
		m:    make(map[string]V, len(d.m)+1),
		keys: make([]K, len(d.keys), len(d.keys)+1),
		encs: make([]string, len(d.encs), len(d.encs)+1),
	}
	copy(c.keys, d.keys)
	copy(c.encs, d.encs)
	for k, v := range d.m {
		c.m[k] = v
	}
	return c
}

// Key is the canonical encoding of a Dict key: Key(a) == Key(b) exactly when
// Eq(a, b) (except that NaN, which is not Eq to itself, is one key). Text,
// Int, Float and Bool are encoded directly (Float -0 as 0); a Time as its
// UTC instant (UnixNano), so the same instant in two locations is one key;
// a Dict as its entries in key order; records, unions, Maybe, Result and
// Date field by field; lists element by element, with nil and empty the
// same. Every variable-length part is length-prefixed, so no two values
// share an encoding. A function cannot be a key: Key panics. (Every field
// of a generated record is exported, `_at` as U__at, so reflect hands Key
// each field's value.)
func Key(k any) string {
	var b strings.Builder
	keyValue(&b, reflect.ValueOf(k))
	return b.String()
}

// dictKey is implemented by every Dict instantiation.
type dictKey interface{ keyAny(b *strings.Builder) }

func writeLen(b *strings.Builder, s string) {
	b.WriteString(strconv.Itoa(len(s)))
	b.WriteByte(':')
	b.WriteString(s)
}

func keyValue(b *strings.Builder, v reflect.Value) {
	if !v.IsValid() {
		b.WriteString("0")
		return
	}
	if v.Type() == timeType && v.CanInterface() {
		b.WriteString("t")
		b.WriteString(strconv.FormatInt(v.Interface().(time.Time).UnixNano(), 10))
		b.WriteByte(';')
		return
	}
	if v.Kind() == reflect.Struct && v.CanInterface() {
		if d, ok := v.Interface().(dictKey); ok {
			d.keyAny(b)
			return
		}
	}
	switch v.Kind() {
	case reflect.String:
		b.WriteString("s")
		writeLen(b, v.String())
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		b.WriteString("i")
		b.WriteString(strconv.FormatInt(v.Int(), 10))
		b.WriteByte(';')
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		b.WriteString("u")
		b.WriteString(strconv.FormatUint(v.Uint(), 10))
		b.WriteByte(';')
	case reflect.Float32, reflect.Float64:
		f := v.Float()
		if f == 0 {
			f = 0 // -0 is 0
		}
		b.WriteString("f")
		b.WriteString(strconv.FormatFloat(f, 'g', -1, 64))
		b.WriteByte(';')
	case reflect.Bool:
		if v.Bool() {
			b.WriteString("T")
		} else {
			b.WriteString("F")
		}
	case reflect.Struct:
		b.WriteString("{")
		for i := range v.NumField() {
			keyValue(b, v.Field(i))
		}
		b.WriteString("}")
	case reflect.Slice, reflect.Array:
		b.WriteString("[")
		b.WriteString(strconv.Itoa(v.Len()))
		b.WriteByte(':')
		for i := range v.Len() {
			keyValue(b, v.Index(i))
		}
		b.WriteString("]")
	case reflect.Pointer:
		if v.IsNil() {
			b.WriteString("n")
			return
		}
		b.WriteString("p")
		keyValue(b, v.Elem())
	case reflect.Interface:
		if v.IsNil() {
			b.WriteString("n")
			return
		}
		b.WriteString("a")
		writeLen(b, v.Elem().Type().String())
		keyValue(b, v.Elem())
	default:
		panic("alder: a value of type " + v.Type().String() + " cannot be a Dict key")
	}
}

// Eq is Alder's one structural equality. The emitter uses it for `==` and
// `!=` on every non-primitive type, and rt/std uses it wherever it compares
// values. Time is compared as an instant (Time.Equal); a Dict by its key set
// and Eq on each value, ignoring insertion order; structs (records, unions,
// Maybe, Result, Date) field by field; slices element-wise, with nil and
// empty equal; union payloads through their pointers; everything else by
// ==. So a Float follows IEEE: NaN is not Eq to itself, and -0 is Eq to 0.
// Every field of a generated record is exported (`_at` is U__at, gen's
// Field), so a Time or Dict in any field is compared as above.
func Eq[T any](a, b T) bool {
	switch x := any(a).(type) {
	case string:
		return x == any(b).(string)
	case int64:
		return x == any(b).(int64)
	case float64:
		return x == any(b).(float64)
	case bool:
		return x == any(b).(bool)
	}
	return eqValue(reflect.ValueOf(&a).Elem(), reflect.ValueOf(&b).Elem())
}

// dictEq is implemented by every Dict instantiation.
type dictEq interface{ eqAny(o any) bool }

var timeType = reflect.TypeFor[time.Time]()

func eqValue(a, b reflect.Value) bool {
	if a.Type() != b.Type() {
		return false
	}
	if a.Type() == timeType && a.CanInterface() {
		return a.Interface().(time.Time).Equal(b.Interface().(time.Time))
	}
	if a.CanInterface() {
		if d, ok := a.Interface().(dictEq); ok && a.Kind() == reflect.Struct {
			return d.eqAny(b.Interface())
		}
	}
	switch a.Kind() {
	case reflect.Struct:
		for i := range a.NumField() {
			if !eqValue(a.Field(i), b.Field(i)) {
				return false
			}
		}
		return true
	case reflect.Slice, reflect.Array:
		if a.Len() != b.Len() {
			return false
		}
		for i := range a.Len() {
			if !eqValue(a.Index(i), b.Index(i)) {
				return false
			}
		}
		return true
	case reflect.Map:
		if a.Len() != b.Len() {
			return false
		}
		for it := a.MapRange(); it.Next(); {
			bv := b.MapIndex(it.Key())
			if !bv.IsValid() || !eqValue(it.Value(), bv) {
				return false
			}
		}
		return true
	case reflect.Pointer, reflect.Interface:
		if a.IsNil() || b.IsNil() {
			return a.IsNil() && b.IsNil()
		}
		if a.Kind() == reflect.Pointer && a.Pointer() == b.Pointer() {
			return true
		}
		return eqValue(a.Elem(), b.Elem())
	case reflect.Func:
		return false // functions have no equality
	default:
		return a.Equal(b)
	}
}

// Date is Alder's calendar `Date` (no time zone).
type Date struct{ Y, M, D int }

// Time converts the date to midnight UTC.
func (d Date) Time() time.Time {
	return time.Date(d.Y, time.Month(d.M), d.D, 0, 0, 0, 0, time.UTC)
}

// DateOf is the UTC calendar date of an instant.
func DateOf(t time.Time) Date {
	y, m, d := t.UTC().Date()
	return Date{Y: y, M: int(m), D: d}
}

// Format renders a date with a Go layout string, e.g. "Jan 2, 2006".
func Format(layout string, d Date) string { return d.Time().Format(layout) }

// HttpError is the stdlib `Http.HttpError`: why an Http.get or Http.post did not produce a 2xx
// response. Status is the response's status code, or 0 when there was no response (a transport
// failure or timeout); Message is the response body, or the error.
type HttpError struct {
	Status  int64
	Message string
}

// Page is a link target: a page's path with its path parameters filled in (each segment
// escaped), and its other parameters as Query, in declaration order. Url.external is a Page
// with the URL as Path and no Query.
type Page struct {
	Path  string
	Query []KV
}

// PageURL is the URL a link to p points at: `href={…}` and `Redirect` render it. It is p's
// Path, then the Query parameters that are not Omit as an URL-encoded query string
// ("/?filter=Active").
func PageURL(p Page) string { return p.Path + queryString(p.Query) }

// PageAt is the URL of a page from its path pattern ("/todos/{id}") and its parameters as text
// (the generated params__M, in declaration order): each {name} segment is the parameter of that
// name, escaped (PathSegment); the others, but those left out (Omit), are the query, in order.
// A message route answers a Rerender without JavaScript with a 303 to it (Post/Redirect/Get).
func PageAt(pattern string, params []KV) string {
	segs := strings.Split(pattern, "/")
	var query []KV
	for _, p := range params {
		filled := false
		for i, s := range segs {
			if s == "{"+p.Key+"}" {
				segs[i], filled = PathSegment(p.Value), true
				break
			}
		}
		if !filled {
			query = append(query, p)
		}
	}
	return PageURL(Page{Path: strings.Join(segs, "/"), Query: query})
}

// KV is one URL parameter: its name and its value as text. Omit leaves it out of the URL: a
// page parameter at its default (QueryKV), which the page decodes back when it is absent.
type KV struct {
	Key, Value string
	Omit       bool
}

// QueryKV is the URL parameter key of a link, left out (Omit) when value is def, the text of
// the parameter's default ("" for a Maybe without one: Nothing).
func QueryKV(key, value, def string) KV { return KV{Key: key, Value: value, Omit: value == def} }

// QueryKVs are the URL parameters of a List page parameter: key once per element, in order.
func QueryKVs(key string, values []string) []KV {
	out := make([]KV, len(values))
	for i, v := range values {
		out[i] = KV{Key: key, Value: v}
	}
	return out
}

// Queries joins groups of URL parameters, in order (a link whose page has List parameters).
func Queries(groups ...[]KV) []KV { return slices.Concat(groups...) }

// queryString is "?k=v&…" for the parameters of kvs that are not Omit, "" for none.
func queryString(kvs []KV) string {
	var b strings.Builder
	for _, p := range kvs {
		if p.Omit {
			continue
		}
		if b.Len() == 0 {
			b.WriteByte('?')
		} else {
			b.WriteByte('&')
		}
		b.WriteString(url.QueryEscape(p.Key) + "=" + url.QueryEscape(p.Value))
	}
	return b.String()
}

// SafeURL reports whether u may be a link or a navigation target: a path of this site (it
// starts with "/" but not "//" or "/\\", which browsers read as another host), a fragment
// ("#…"), or an absolute http: or https: URL with a host (the scheme in any case). Anything else
// — javascript:, data:, other schemes, protocol-relative URLs, leading whitespace, or any
// control character (< 0x20 or 0x7f) anywhere — is refused. Url.external turns a refused URL into "#"; html renders such an href
// as "#", and rt/web refuses to redirect to one.
func SafeURL(u string) bool {
	// browsers drop tabs and newlines inside a URL ("/\t/evil" is "//evil"): no control byte
	for i := 0; i < len(u); i++ {
		if u[i] < 0x20 || u[i] == 0x7f {
			return false
		}
	}
	switch {
	case strings.HasPrefix(u, "#"):
		return true
	case strings.HasPrefix(u, "/"):
		return !strings.HasPrefix(u, "//") && !strings.HasPrefix(u, "/\\")
	}
	l := strings.ToLower(u)
	if !strings.HasPrefix(l, "http://") && !strings.HasPrefix(l, "https://") {
		return false
	}
	p, err := url.Parse(u)
	return err == nil && p.Host != ""
}

// URLScheme is the scheme of u as an error message names it ("javascript:"), or u quoted when
// it has none.
func URLScheme(u string) string {
	if i := strings.IndexByte(u, ':'); i > 0 && !strings.ContainsAny(u[:i], "/?#") {
		return strings.ToLower(u[:i]) + ":"
	}
	return strconv.Quote(u)
}

// PathSegment is a path parameter's text escaped as one segment of a URL path ("a/b" →
// "a%2Fb").
func PathSegment(s string) string { return url.PathEscape(s) }

// MsgURL is the URL a message is posted to: /_m/<module>/<msg>, then the message's parameters
// (in declaration order) as an URL-encoded query string. Generated views do not call it: they
// render a MsgRef, whose URL also carries the parameters of the page being rendered.
func MsgURL(module, msg string, params ...KV) string {
	return MsgRef{Module: module, Msg: msg, Params: params}.URL(nil)
}

// MsgRef is a message as a `click` or `submit` attribute names it: its module (the page's, or
// App), its name and its parameters as text, in declaration order (a List parameter once per
// element). rt/html resolves it to a URL when the page is rendered (URL).
type MsgRef struct {
	Module, Msg string
	Params      []KV
}

// PagePrefix starts the query keys of a message URL that carry the parameters of the page the
// message was rendered on ("_p.filter"): an Alder name never contains '.', so they never clash
// with the message's own parameters.
const PagePrefix = "_p."

// URL is the URL m is posted to: /_m/<module>/<msg>, the message's parameters, then page, the
// parameters of the page rendering it, each key prefixed with PagePrefix — the message's route
// decodes the page's parameters from those (PageParams), so update and the re-render see the
// page the user saw.
func (m MsgRef) URL(page []KV) string {
	kvs := m.Params
	if len(page) > 0 {
		kvs = slices.Clone(m.Params)
		for _, p := range page {
			p.Key = PagePrefix + p.Key
			kvs = append(kvs, p)
		}
	}
	return "/_m/" + m.Module + "/" + m.Msg + queryString(kvs)
}

// Key identifies m as a form posting it is rendered (FormState.Msg): MsgKey of its path and its
// own parameters.
func (m MsgRef) Key() string {
	q := url.Values{}
	for _, p := range m.Params {
		if !p.Omit {
			q[p.Key] = append(q[p.Key], p.Value)
		}
	}
	return MsgKey("/_m/"+m.Module+"/"+m.Msg, q)
}

// MsgKey identifies a message as it was sent: its path, then its own parameters — the query's
// keys without the PagePrefix ones — URL-encoded in key order. A message route puts it on the
// form state of a re-render (FormState.Msg), so only the form that posted that very message (a
// per-row form's row id included) shows the submitted values and errors; MsgRef.Key is the same
// for the form as rendered.
func MsgKey(path string, query url.Values) string {
	own := url.Values{}
	for k, vs := range query {
		if !strings.HasPrefix(k, PagePrefix) {
			own[k] = vs
		}
	}
	if len(own) == 0 {
		return path
	}
	return path + "?" + own.Encode()
}

// PageParams are the parameters of the page a message was sent from, for the message's route
// to decode, taken from the PagePrefix keys of the message URL's query (prefix removed): as a
// map of each key's first value (the path parameters) and as url.Values (the others).
func PageParams(query url.Values) (map[string]string, url.Values) {
	params, q := map[string]string{}, url.Values{}
	for k, vs := range query {
		if name, ok := strings.CutPrefix(k, PagePrefix); ok && len(vs) > 0 {
			params[name] = vs[0]
			q[name] = vs
		}
	}
	return params, q
}

// BackURL is where a redirect back to the page that sent a request goes: the path and query of
// referer (the Referer header), or "/" when there is none. Scheme and host are dropped, so it
// never leads out of the app.
func BackURL(referer string) string {
	u, err := url.Parse(referer)
	if err != nil || referer == "" {
		return "/"
	}
	p := u.EscapedPath()
	if !strings.HasPrefix(p, "/") || strings.HasPrefix(p, "//") || strings.HasPrefix(p, "/\\") {
		return "/"
	}
	if u.RawQuery != "" {
		p += "?" + u.RawQuery
	}
	return p
}

// MaybeText is a Maybe's value as text, "" for Nothing. The generated code uses it for message
// parameters and form values of a Maybe type.
func MaybeText[T any](m Maybe[T], text func(T) string) string {
	if !m.Ok {
		return ""
	}
	return text(m.Val)
}

// TextOf is any other value as text (fmt's %v), for message parameters of a type with no text
// form of its own (records, lists, unions with payloads).
func TextOf(v any) string { return fmt.Sprint(v) }

// Concat joins the pieces of an interpolated string.
func Concat(parts ...string) string { return strings.Join(parts, "") }

// OrElse is the `??` operator.
func OrElse[T any](m Maybe[T], d T) T {
	if m.Ok {
		return m.Val
	}
	return d
}

// Append is `++` on lists. The result never shares storage with a or b.
func Append[T any](a, b []T) []T {
	out := make([]T, 0, len(a)+len(b))
	out = append(out, a...)
	return append(out, b...)
}

// Unit is Alder's `Unit` value.
func Unit() struct{} { return struct{}{} }

// DateCmp orders dates: negative when a is before b, 0 when equal, positive when after. The
// emitter uses it for `<`, `<=`, `>`, `>=` on Date.
func DateCmp(a, b Date) int {
	switch {
	case a.Y != b.Y:
		return a.Y - b.Y
	case a.M != b.M:
		return a.M - b.M
	}
	return a.D - b.D
}

// TimeCmp orders instants like DateCmp: the emitter uses it for ordered comparisons on Time.
func TimeCmp(a, b time.Time) int { return a.Compare(b) }

// Int is the identity on Int. The emitter routes a literal through it where Go would otherwise
// evaluate an operator at compile time (`9223372036854775807 + 1`, `1 / 0`): Alder's Int
// arithmetic wraps on overflow and fails at run time on division by zero, and Go only does that
// for values, not constants.
func Int(n int64) int64 { return n }

// Float is the identity on Float, for the same purpose as Int (`1.0 / 0.0` is +Inf at run time).
func Float(f float64) float64 { return f }
